import java.util.*; // 只用到链表节点，不依赖集合工具

class Solution {
    public ListNode reverseList(ListNode head) {
        ListNode previous = null;
        ListNode current = head;

        while (current != null) {
            // 改写 next 前先抓住后继，否则后半段会断
            ListNode next = current.next;

            // 当前边改为指向前驱
            current.next = previous;

            // 前驱跟上刚反转的节点，当前指针走到原后继
            previous = current;
            current = next;
        }

        // 原尾节点没有更后的节点，它就是新头
        return previous;
    }
}

import java.util.*;

class Solution {
    public ListNode reverseBetween(ListNode head, int left, int right) {
        if (left < 1 || right < left) throw new IllegalArgumentException("invalid interval");
        // left 为 1 时头会变，哑节点让返回值始终是 dummy.next
        ListNode dummy = new ListNode(0, head);
        ListNode pre = dummy;

        // 只走到待反转段前一个，后面头插都挂在 pre 后面
        for (int i = 1; i < left; i++) {
            pre = pre.next;
        }

        // 钉住原左端点，它逐次变成区间尾，不能跟着前移
        ListNode current = pre.next;

        // 每次把 current 的后继摘下，插到 pre 后面，相当于头插
        for (int i = 0; i < right - left; i++) {
            ListNode moved = current.next;
            current.next = moved.next;
            moved.next = pre.next;
            pre.next = moved;
        }

        return dummy.next;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public ListNode swapPairs(ListNode head) {
        ListNode dummy = new ListNode(0, head);
        ListNode previous = dummy;

        while (previous.next != null && previous.next.next != null) {
            ListNode first = previous.next;
            ListNode second = first.next;

            // 先改三条边：previous 接 second，first 接原后继，second 再接 first。
            previous.next = second;
            first.next = second.next;
            second.next = first;

            // first 已是本组尾，下一对从其后方开始，避免重复交换。
            previous = first;
        }
        return dummy.next;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        if (k <= 0) throw new IllegalArgumentException("positive k required");
        ListNode dummy = new ListNode(0, head);
        ListNode groupPrev = dummy;

        while (true) {
            // 走不满 k 步说明尾部不足一组，保持原顺序。
            ListNode kth = getKth(groupPrev, k);
            if (kth == null) break;

            ListNode groupNext = kth.next;

            // previous 从下一段起点开始，组尾反转后自然接上 groupNext。
            ListNode previous = groupNext;
            ListNode current = groupPrev.next;
            while (current != groupNext) {
                ListNode next = current.next;
                current.next = previous;
                previous = current;
                current = next;
            }

            // 反转前的组首变成组尾，作为下一组的前驱。
            ListNode oldStart = groupPrev.next;
            groupPrev.next = kth;
            groupPrev = oldStart;
        }
        return dummy.next;
    }

    private ListNode getKth(ListNode start, int k) {
        while (start != null && k > 0) {
            start = start.next;
            k--;
        }
        return start;
    }
}

import java.util.*;

class Solution {
    public void reorderList(ListNode head) {
        if (head == null || head.next == null) {
            return;
        }

        // 要求 fast 还能再走两步，slow 才停在前半段最后一个
        ListNode slow = head;
        ListNode fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // 先断开，反转后的后半段才不会和前半段缠在一起
        ListNode second = slow.next;
        slow.next = null;
        second = reverse(second);

        // 先接 second，再把 second 接回 first 原来的后继
        ListNode first = head;
        while (second != null) {
            ListNode firstNext = first.next;
            ListNode secondNext = second.next;

            first.next = second;
            second.next = firstNext;

            first = firstNext;
            second = secondNext;
        }
    }

    private ListNode reverse(ListNode head) {
        ListNode previous = null;
        ListNode current = head;
        while (current != null) {
            ListNode next = current.next;
            current.next = previous;
            previous = current;
            current = next;
        }
        return previous;
    }
}

