public class Solution {
    public ListNode detectCycle(ListNode head) {
        ListNode slow = head;
        ListNode fast = head;

        // 先确认有环，并得到环内的相遇点
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;

            if (slow == fast) {
                // 一个从头出发，一个从相遇点出发，同速走到的交点即入口
                ListNode seeker = head;
                while (seeker != slow) {
                    seeker = seeker.next;
                    slow = slow.next;
                }
                return seeker;
            }
        }
        return null;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        if (n <= 0) throw new IllegalArgumentException("positive n required");
        // 哑节点统一承接原头，删头时不用另写分支。
        ListNode dummy = new ListNode(0, head);
        ListNode fast = dummy;
        ListNode slow = dummy;

        // 只走 fast，使它比 slow 超前 n 个节点。
        for (int i = 0; i < n; i++) {
            fast = fast.next;
            if (fast == null) throw new IllegalArgumentException("n exceeds length");
        }

        // fast 停在尾时，slow 正好停在待删节点的前驱。
        while (fast.next != null) {
            fast = fast.next;
            slow = slow.next;
        }

        slow.next = slow.next.next; // 绕过 slow 的后继，完成删除。
        return dummy.next;
    }
}

import java.util.*; // 只用到链表节点，不依赖集合工具

class Solution {
    public boolean isPalindrome(ListNode head) {
        if (head == null || head.next == null) return true;

        // 快指针两步、慢指针一步，slow 停在后半段起点
        ListNode slow = head;
        ListNode fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // 反转后半段后，right 成为从原尾往中点的起点
        ListNode right = reverse(slow);
        ListNode left = head;
        ListNode rightHead = right; // 留住后半段新头，比较完才能复原

        // 后半段不长于可比较的前半段，right 走完即可
        boolean result = true;
        while (right != null) {
            if (left.val != right.val) {
                result = false;
                break;
            }
            left = left.next;
            right = right.next;
        }

        // 再反转一次，把后半段 next 恢复成进入函数时的方向
        reverse(rightHead);
        return result;
    }

    private ListNode reverse(ListNode head) {
        ListNode previous = null;
        while (head != null) {
            ListNode next = head.next;
            head.next = previous;
            previous = head;
            head = next;
        }
        return previous;
    }
}

import java.util.*; // 双指针只沿 next 切换，不使用集合

public class Solution {
    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        ListNode a = headA;
        ListNode b = headB;

        // 走完本链就换到另一条头，两指针都走完两条链的总长度
        while (a != b) {
            a = (a == null) ? headB : a.next;
            b = (b == null) ? headA : b.next;
        }

        // 相遇处是第一个共享节点；没有交点时这里是 null
        return a;
    }
}

