class Solution {
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        // 虚拟头让第一条边也走 tail.next，不必单独处理结果头
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;

        while (list1 != null && list2 != null) {
            if (list1.val <= list2.val) {
                tail.next = list1;
                list1 = list1.next;
            } else {
                tail.next = list2;
                list2 = list2.next;
            }
            tail = tail.next;
        }

        // 剩下的那条已经有序，整段接上即可
        tail.next = (list1 != null) ? list1 : list2;
        return dummy.next;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public ListNode mergeKLists(ListNode[] lists) {
        // 堆里只放每条链尚未合并的头，比较的是节点值。
        PriorityQueue<ListNode> heap = new PriorityQueue<>(
                Comparator.comparingInt(node -> node.val)
        );

        for (ListNode head : lists) {
            if (head != null) heap.offer(head);
        }

        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;

        while (!heap.isEmpty()) {
            // 弹出的是当前所有链表头里最小的节点。
            ListNode node = heap.poll();
            tail.next = node;
            tail = tail.next;

            // 后继成为该链新的候选，再放回堆。
            if (node.next != null) heap.offer(node.next);
        }
        return dummy.next;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) return head;

        // fast 先走一步，避免 slow 停在后半段，方便从中点断开。
        ListNode slow = head;
        ListNode fast = head.next;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        ListNode rightHead = slow.next;
        slow.next = null;

        // 左右各自有序后再线性合并。
        ListNode left = sortList(head);
        ListNode right = sortList(rightHead);
        return merge(left, right);
    }

    private ListNode merge(ListNode a, ListNode b) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;

        while (a != null && b != null) {
            if (a.val <= b.val) {
                tail.next = a;
                a = a.next;
            } else {
                tail.next = b;
                b = b.next;
            }
            tail = tail.next;
        }
        tail.next = (a != null) ? a : b;
        return dummy.next;
    }
}

import java.util.*; // 只用到链表节点，不依赖集合工具

class Solution {
    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        int carry = 0;

        // 末尾若还有进位，也要再生成一位，所以 carry 留在循环条件里
        while (l1 != null || l2 != null || carry != 0) {
            int x = (l1 != null) ? l1.val : 0;
            int y = (l2 != null) ? l2.val : 0;
            int sum = x + y + carry;

            carry = sum / 10;                 // 十位留给下一位
            tail.next = new ListNode(sum % 10); // 个位作为当前结果节点
            tail = tail.next;

            if (l1 != null) l1 = l1.next;
            if (l2 != null) l2 = l2.next;
        }
        return dummy.next;
    }
}

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        ListNode current = head;

        while (current != null && current.next != null) {
            if (current.val == current.next.val) {
                // 升序下重复值连在一起，摘掉后一个即可
                // current 先不动：新的后继可能还是同一个值
                current.next = current.next.next;
            } else {
                current = current.next;
            }
        }

        return head;
    }
}

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        ListNode dummy = new ListNode(0, head);
        ListNode pre = dummy;
        ListNode current = head;

        while (current != null) {
            // 升序下相同值连在一起，与后继相同就要整段删掉
            if (current.next != null && current.val == current.next.val) {
                int duplicateValue = current.val;

                while (current != null && current.val == duplicateValue) {
                    current = current.next;
                }

                // pre 停在上一个保留结点，直接跨过这一整段
                pre.next = current;
            } else {
                // 与后继不同，这个值只出现一次，可以接到保留链上
                pre = current;
                current = current.next;
            }
        }

        return dummy.next;
    }
}

// LC138 输入是有限、next 无环的链表，random 仅指向本条链上的节点或 null，头节点可为 null。主穿插法还要求允许临时改写原 next，正常完成后恢复原链；有只读或共享并发读取约束时，改用以节点身份为键的映射法，需 O(n) 工作空间。
import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) return null;

        // 复制节点紧挨原节点，后面才能用 next 找到对应副本。
        Node current = head;
        while (current != null) {
            Node copy = new Node(current.val);
            copy.next = current.next;
            current.next = copy;
            current = copy.next;
        }

        // A.random.next 就是 A.random 的副本，赋给 A'。
        current = head;
        while (current != null) {
            if (current.random != null) {
                current.next.random = current.random.next;
            }
            current = current.next.next;
        }

        // 原链 next 跳回下一个原节点，复制链 next 跳到下一个副本。
        Node newHead = head.next;
        current = head;
        while (current != null) {
            Node copy = current.next;
            current.next = copy.next;
            copy.next = (copy.next == null) ? null : copy.next.next;
            current = current.next;
        }
        return newHead;
    }
}
